const now = new Date().toISOString();
const body = $json.body || $json;
return [{ json: {
  ok: true,
  kind: 'telegram_operator_alert',
  receivedAt: now,
  alert: {
    severity: body.severity || 'info',
    title: body.title || 'Jarvis Alert',
    message: body.message || 'Alert received',
    nextAction: body.nextAction || 'Review Jarvis status'
  },
  original: body
} }];
